import hashlib

def modify_kickstart_config(config_path, params, password):
    placeholder_pattern = r'{{(.*?)}}'
    new_password = hashlib.sha256(password.encode()).hexdigest()

    try:
        with open(config_path, 'r') as file:
            config_content = file.read()

        for key, value in params.items():
            config_content = config_content.replace(f'{{{key}}}', str(value))

        config_content += f'\n{{password: {new_password}}}\n'

        with open('new_config.conf', 'w') as new_file:
