import json

class JSONHandler:
    _registry = {}

    @classmethod
    def register_factory(cls, id, factory):
        cls._registry[id] = factory

    @classmethod
    def from_json_string(cls, json_string, id):
        data = json.loads(json_string)
        if id in cls._registry:
            return cls._registry[id](data)
        else:
            raise ValueError(""No factory registered for ID: {}"".format(id))

    def to_json_string(self):
        return json.dumps(self.__dict__)

class SubClassJSONHandler(JSONHandler):
    @classmethod
    def from_json_string(cls, data):
        instance = super().from_json_string(data, 'subclass')
        # Custom initialization or processing for subclasses
        return instance

# Example usage:
def create_subclass_instance(data):
    return SubClassJSONHandler(**data)

JSONHandler.register_factory('subclass', create_subclass_instance)

json_data = '{""id"": ""subclass"", ""name"": ""Example"", ""value"": 42}'
instance = JSONHandler.from_json_string(json_data, 'subclass')
print(instance.to_json_string())
