import csv

def validate_csv(file_path):
    required_columns = {'Name', 'Age', 'Gender', 'City'}
    error_messages = []

    with open(file_path, mode='r') as file:
        reader = csv.DictReader(file)

        # Check if all required columns are present
        if not required_columns.issubset(reader.fieldnames):
            error_messages.append(""Missing one or more of the required columns: Name, Age, Gender, City."")
            return False

        for row in reader:
            # Validate Name
            if not isinstance(row['Name'], str) or not row['Name']:
                error_messages.append(f""Invalid 'Name' value found: {row['Name']}. It should be a non-empty string."")

            # Validate Age
            try:
                age = int(row['Age'])
                if age <= 0:
                    error_messages.append(f""Invalid 'Age' value found: {age}. It should be a positive integer."")
            except ValueError:
                error_messages.append(f""Invalid 'Age' value found: {row['Age']}. It should be a positive integer."")

            # Validate Gender
            if row['Gender'] not in {'Male', 'Female'}:
                error_messages.append(f""Invalid 'Gender' value found: {row['Gender']}. It should be either 'Male' or 'Female'."")

            # Validate City
            if not isinstance(row['City'], str) or not row['City']:
                error_messages.append(f""Invalid 'City' value found: {row['City']}. It should be a non-empty string."")

    if error_messages:
        for message in error_messages:
            print(message)
        return False

    return True
