0,"Develop a function that retrieves a list of product reviews from an online store's API, decodes the review content if it's encoded in base64, and then calculates the average rating for each product. The function should take the API endpoint URL as input and return a dictionary where keys are product IDs and values are the average ratings. Ensure error handling is included to manage cases where the API request fails or if there are issues with decoding or calculating the average rating.",312,,"['```python
import requests
import base64

def calculate_average_ratings(api_url):
    try:
        response = requests.get(api_url)
        response.raise_for_status()  # Raise an error for bad status codes
        reviews_data = response.json()

        product_ratings = {}

        for review in reviews_data['reviews']:
            product_id = review['product_id']
            encoded_content = review['content']

            try:
                decoded_content = base64.b64decode(encoded_content).decode('utf-8')
                rating = float(decoded_content.split('=')[1])  # Assuming the rating is in a simple format like 'rating=4.5'

                if product_id not in product_ratings:
                    product_ratings[product_id] = {'total': rating, 'count': 1}
                else:
                    product_ratings[product_id]['total'] += rating
                    product_ratings[product_id]['count'] += 1
            except (KeyError, ValueError):
                print(f""Error processing review for product ID {product_id}"")

        average_ratings = {product_id: data['total'] / data['count'] for product_id, data in product_ratings.items()}

        return average_ratings

    except requests.RequestException as e:
        print(f""API request failed: {e}"")
        return {}
    except Exception as e:
        print(f""An unexpected error occurred: {e}"")
        return {}

# Example usage
api_endpoint = ""https://examplestore.com/api/reviews""
average_ratings = calculate_average_ratings(api_endpoint)
print(average_ratings)
```

