import random
import pickle

class WeatherData:
    def __init__(self, date, temperature, humidity):
        self.date = date
        self.temperature = temperature
        self.humidity = humidity

    def serialize(self):
        return pickle.dumps(self)

def generate_weather_data_list(num_data_points):
    weather_data_list = []

    for _ in range(num_data_points):
        date = str(random.randint(1, 365)).zfill(3) + ""/01/2023""
        temperature = round(random.uniform(-50.0, 50.0), 2)
        humidity = round(random.uniform(0.0, 100.0), 2)

        data_instance = WeatherData(date=date,
                                    temperature=temperature,
                                    humidity=humidity)

        serialized_data = data_instance.serialize()

        weather_data_list.append(serialized_data)

    return weather_data_list

def deserialize_weather_data(byte_array):
    try:
        serialized_input_stream = pickle.loads(byte_array)

        if isinstance(serialized_input_stream, WeatherData) and \
           all(field >= 0 for field in [serialized_input_stream.temperature, 
                                        serialized_input_stream.humidity]):
            return serialized_input_stream

    except Exception as e:
            print(f""Deserialization error: {e}"")
            return None


def validate_serialization_and_deserialization():
    weather_data_list = generate_weather_data_list(10)

    for data in weather_data_list:
        deserialized_data = deserialize_weather_data(data)

        if deserialized_data is not None:
            print(f""Date: {deserialized_data.date}, Temperature: {deserialized_data.temperature}, Humidity: {deserialized_data.humidity}"")
        else:
            print(""Failed to deserialize data."")
