import socket
import random
import ipaddress
from datetime import datetime

class SOCKET_ADDRESS:
    def __init__(self, ip, port, protocol, interface):
        self.ip = ip
        self.port = port
        self.protocol = protocol
        self.interface = interface

def generate_random_ip():
    return str(ipaddress.IPv4Address(random.randint(0, 2**32 - 1)))

def generate_random_port(start=1024, end=65535):
    return random.randint(start, end)

def get_protocols():
    protocols = ['TCP', 'UDP', 'ICMP']
    return random.choice(protocols)

def get_interfaces():
    interfaces = ['eth0', 'wlan0', 'lo']
    return random.choice(interfaces)

def validate_address(address):
    try:
        socket.inet_pton(socket.AF_INET, address)
        return True
    except socket.error:
        return False

def log_activity(log_file, message):
    with open(log_file, 'a') as file:
        file.write(f""{datetime.now()} - {message}\n"")

def create_socket_address_list(num_addresses, expected_count, log_file='network_log.txt'):
    address_list = []
    for _ in range(expected_count):
        ip = generate_random_ip()
        if not validate_address(ip):
            log_activity(log_file, f""Invalid IP generated: {ip}"")
            continue
        port = generate_random_port()
        protocol = get_protocols()
        interface = get_interfaces()

        address = SOCKET_ADDRESS(ip, port, protocol, interface)
        address_list.append(address)

    if len(address_list) != expected_count:
        log_activity(log_file, f""Failed to create all {expected_count} addresses. Only created {len(address_list)}"")

    return address_list

# Example usage
num_addresses = 10
expected_count = num_addresses * 2  # Double the number for demonstration purposes
addresses = create_socket_address_list(num_addresses, expected_count)
for addr in addresses:
    print(addr.ip, addr.port, addr.protocol, addr.interface)
```

