# Mock cache dictionary
cache = {}

async def fetch_page(session, url):
    async with session.get(url) as response:
        if response.status == 200:
            return await response.json()
        else:
            raise Exception(f""Failed to retrieve data: {response.status}"")

async def process_reviews(api_url, start_date=None, end_date=None, role_filter=None, page=1):
    async with aiohttp.ClientSession() as session:
        params = {
            'page': page,
            # Add other parameters if required by the API
        }
        if start_date and end_date:
            params['start_date'] = start_date
            params['end_date'] = end_date
        if role_filter:
            params['role'] = role_filter

        url = f""{api_url}?{urlencode(params)}""
        try:
            data = await fetch_page(session, url)
            reviews = data.get('reviews', [])
            products = {}

            for review in reviews:
                product_id = review['product_id']
                rating = review['rating']
                content = review.get('content')

                if content and content.startswith('base64:'):
                    try:
                        decoded_content = base64.b64decode(content.split(':')[1]).decode('utf-8')
                        review['content'] = decoded_content
                    except Exception as e:
                        print(f""Failed to decode content for product {product_id}: {e}"")

                if product_id not in products:
                    products[product_id] = {'total_rating': 0, 'review_count': 0}

                products[product_id]['total_rating'] += rating
                products[product_id]['review_count'] += 1

            return products, data.get('has_next', False)
        except Exception as e:
            print(f""Error processing reviews: {e}"")
            return {}, False

async def retrieve_product_reviews(api_url: str, start_date: str = None, end_date: str = None, role_filter: str = None) -> dict:
    products_with_ratings = {}
    page = 1
    has_next_page = True

    while has_next_page:
        cached_key = f""{api_url}_{start_date}_{end_date}_{role_filter}_{page}""
        if cached_key in cache and time.time() - cache[cached_key]['timestamp'] < 3600:  # Cache for 1 hour
            products_with_ratings.update(cache[cached_key]['data'])
            has_next_page = False
        else:
            try:
                new_products, has_next_page = await process_reviews(api_url, start_date, end_date, role_filter, page)
                products_with_ratings.update(new_products)
                cache[cached_key] = {'data': products_with_ratings, 'timestamp': time.time()}
                page += 1
            except Exception as e:
                print(f""Error fetching reviews: {e}"")
                break

    average_ratings = {product_id: data['total_rating'] / data['review_count'] for product_id, data in products_with_ratings.items() if data['review_count']}
    return average_ratings

# Example usage
api_url = ""https://example.com/api/reviews""
start_date = ""2023-01-01""
end_date = ""2023-12-31""
role_filter = ""verified_buyer""

asyncio.run(retrieve_product_reviews(api_url, start_date=start_date, end_date=end_date, role_filter=role_filter))
