0,"Create a function in Python that constructs a GraphQL query based on a given dictionary of fields and their corresponding values. The function should accept the dictionary containing field names and values, the GraphQL endpoint URL, and the initial GraphQL query as input. It should then generate a properly formatted GraphQL query with embedded variable values for each field specified in the input dictionary, and return the constructed GraphQL query string.",89,,"[""```python
import requests

def construct_graphql_query(variables, url, initial_query):
    # Create a list to hold the fields for the final query
    fields = []

    # Iterate through the variables dictionary to build field strings
    for key, value in variables.items():
        if isinstance(value, dict):
            nested_fields = construct_nested_fields(value)
            field_string = f'{key} {{ {nested_fields} }}'
        else:
            field_string = key
        fields.append(field_string)

    # Join all fields with a space to form the final query string
    final_query = initial_query + ' '.join(fields) + '}'

    return final_query

def construct_nested_fields(nested_dict):
    nested_fields = []
    for key, value in nested_dict.items():
        if isinstance(value, dict):
