0,"Create a Python function that utilizes the `psutil` library to monitor system resources. The function should accept a process ID as an argument and return a dictionary containing the CPU usage, memory usage, and disk I/O statistics for that process. Additionally, the function should have an optional boolean parameter to indicate whether to include network I/O statistics in the returned dictionary. The output should exclude processes marked as 'zombie' or with no running child processes.",295,,"[""```python
import psutil

def monitor_process(process_id, include_network=False):
    try:
        process = psutil.Process(process_id)
        if process.status() == psutil.STATUS_ZOMBIE or not process.children():
            return None

        cpu_usage = process.cpu_percent(interval=1)
        memory_info = process.memory_info()
        disk_io_stats = process.disk_io_counters()

        stats_dict = {
            'cpu_usage': cpu_usage,
            'memory_usage': memory_info.rss / 1024 / 1024,  # Convert bytes to MB
            'disk_read_bytes': disk_io_stats.read_bytes,
            'disk_write_bytes': disk_io_stats.write_bytes
        }

        if include_network:
            net_io_stats = process.net_io_counters()
            stats_dict.update({
                'net_read_bytes': net_io_stats.bytes_recv,
                'net_write_bytes': net_io_stats.bytes_sent
            })

        return stats_dict

    except psutil.NoSuchProcess:
        return None

# Example usage:
# print(monitor_process(1234, include_network=True))
```

