import uuid
import hashlib

def generate_unique_identifier():
    return str(uuid.uuid4())

def validate_input(system_id, user_role, permission_level):
    # Example validation logic
    if not isinstance(system_id, int) or system_id < 0:
        raise ValueError(""System ID must be a non-negative integer"")
    if not isinstance(user_role, str) or len(user_role.strip()) == 0:
        raise ValueError(""User role must be a non-empty string"")
    if not isinstance(permission_level, int) or permission_level < 0:
        raise ValueError(""Permission level must be a non-negative integer"")

def hash_identifier(identifier):
    return hashlib.sha256(identifier.encode()).hexdigest()

def save_configuration_to_file(config_id, config_details, file_path='configurations.txt'):
    with open(file_path, 'a') as file:
        file.write(f""{config_id}: {config_details}\n"")

def process_configuration(system_id, user_role, permission_level):
    try:
        validate_input(system_id, user_role, permission_level)
        unique_identifier = generate_unique_identifier()
        hashed_identifier = hash_identifier(unique_identifier)
        save_configuration_to_file(hashed_identifier, f""System ID: {system_id}, User Role: {user_role}, Permission Level: {permission_level}"")
        return f""Configuration processed successfully with identifier: {hashed_identifier}""
    except ValueError as e:
        return str(e)

# Example usage
result = process_configuration(101, ""admin"", 3)
print(result)
