import csv
import re

def validate_csv(csv_path):
    validation_errors = []

    required_columns = {'Name', 'Age', 'Gender', 'City'}
    with open(csv_path, 'r') as file:
        reader = csv.DictReader(file)
        headers = set(reader.fieldnames)

        if not required_columns.issubset(headers):
            validation_errors.append(""Missing required columns: "" + ', '.join(required_columns - headers))

    with open(csv_path, 'r') as file:
        reader = csv.DictReader(file)

        for row in reader:
            if not isinstance(row['Name'], str) or not row['Name']:
                validation_errors.append(""Invalid Name: "" + row['Name'])

            if not isinstance(row['Age'], int) or row['Age'] <= 0:
                validation_errors.append(""Invalid Age: "" + str(row['Age']))

            if row['Gender'] not in ['Male', 'Female']:
                validation_errors.append(""Invalid Gender: "" + row['Gender'])

            if not isinstance(row['City'], str) or not row['City']:
                validation_errors.append(""Invalid City: "" + row['City'])

            if len(re.findall(r'[^a-zA-Z\s]', row['City'])) > 0:
                validation_errors.append(f""Non-alphabetic characters in City: {row['City']}"")

    return True if not validation_errors else False, '\n'.join(validation_errors)

# Example usage
csv_path = 'path_to_your_file.csv'
