import json

class JSONHandler:
    _registry = {}

    @classmethod
    def register(cls, id, factory):
        cls._registry[id] = factory

    @classmethod
    def from_json_string(cls, json_str):
        data = json.loads(json_str)
        instance_id = data.get('id')
        if instance_id in cls._registry:
            factory = cls._registry[instance_id]
            return factory(data)
        else:
            raise ValueError(f""Unknown ID: {instance_id}"")

    def to_json_string(self):
        return json.dumps(self.__dict__)

class SubClass1(JSONHandler):
    @classmethod
    def from_json_data(cls, data):
        return cls(**data)

    def __init__(self, value1, value2):
        self.value1 = value1
        self.value2 = value2

# Example usage:
JSONHandler.register(1, SubClass1.from_json_data)
instance_str = '{""id"": 1, ""value1"": ""a"", ""value2"": ""b""}'
instance = JSONHandler.from_json_string(instance_str)
print(instance.to_json_string())  # Output: {""value1"": ""a"", ""value2"": ""b""}
