import hashlib
import json
import logging
from cryptography.fernet import Fernet

# Initialize logger
logging.basicConfig(level=logging.INFO, filename='system_config.log', filemode='a',
                    format='%(name)s - %(levelname)s - %(message)s')

class ConfigManager:
    def __init__(self):
        self.encryption_key = Fernet.generate_key()
        self.cipher_suite = Fernet(self.encryption_key)
        self.config_store = {}

    def validate_input(self, input_data, validation_rules):
        for rule in validation_rules:
            if not rule(input_data):
                raise ValueError(f""Invalid input: {input_data}"")
        return True

    def generate_unique_id(self, data):
        unique_id = hashlib.sha256(data.encode()).hexdigest()
        return self.cipher_suite.encrypt(unique_id.encode())

    def validate_unique_id(self, encrypted_id):
        try:
            decrypted_id = self.cipher_suite.decrypt(encrypted_id).decode()
            return hashlib.sha256(decrypted_id.encode()).hexdigest() == encrypted_id.decode()
        except (Fernet.InvalidToken, UnicodeDecodeError):
            raise ValueError(""Invalid unique ID"")

    def store_config(self, config_data):
        encrypted_data = self.cipher_suite.encrypt(json.dumps(config_data).encode())
        self.config_store[encrypted_data] = True
        logging.info(f""Stored configuration: {config_data}"")

    def retrieve_config(self, encrypted_id):
        if not self.validate_unique_id(encrypted_id):
            raise ValueError(""Invalid unique ID for retrieval"")
        decrypted_data = self.cipher_suite.decrypt(encrypted_id).decode()
        return json.loads(decrypted_data)

# Example usage
def main():
    config_manager = ConfigManager()

    # Define validation rules
    def is_valid_system_id(system_id):
        return isinstance(system_id, str) and len(system_id) > 0

    def is_valid_role(role):
        valid_roles = ['admin', 'user', 'guest']
        return role in valid_roles

    config_data = {
        ""system_id"": ""sys123"",
        ""role"": ""admin""
    }

    # Validate inputs
    validation_rules = [is_valid_system_id, is_valid_role]
    config_manager.validate_input(config_data, validation_rules)

    # Generate and validate unique ID
    encrypted_id = config_manager.generate_unique_id(json.dumps(config_data))
    print(""Encrypted ID:"", encrypted_id)
    assert config_manager.validate_unique_id(encrypted_id), ""Unique ID validation failed""

    # Store and retrieve configuration
    config_manager.store_config(config_data)
    retrieved_config = config_manager.retrieve_config(encrypted_id)
    print(""Retrieved Configuration:"", retrieved_config)

if __name__ == ""__main__"":
    main()
