import bcrypt

def hash_password(plaintext_password, cost_factor=12):
    try:
        # Hash the password with the specified cost factor
        hashed_password = bcrypt.hashpw(plaintext_password.encode('utf-8'), bcrypt.gensalt(cost_factor))
        return hashed_password
    except Exception as e:
        return f""Error hashing password: {str(e)}""

def verify_password(stored_hash, provided_password):
    try:
        # Verify the provided password against the stored hash
        if bcrypt.checkpw(provided_password.encode('utf-8'), stored_hash):
            return True
        else:
            return False
    except Exception as e:
        return f""Error verifying password: {str(e)}""

def update_cost_factor(stored_hash, new_cost_factor):
    try:
        # Rehash the password with a new cost factor for enhanced security
        if bcrypt.checkpw(bcrypt.gensalt(new_cost_factor).decode('utf-8'), stored_hash):
            return hash_password(stored_hash.decode('utf-8'), new_cost_factor)
        else:
            raise ValueError(""Failed to update cost factor due to hash mismatch."")
    except Exception as e:
        return f""Error updating cost factor: {str(e)}""
```

