from datetime import datetime, timedelta

# Simulated database for storing hashed passwords and their complexity levels
database = {}

def hash_password(password: str, complexity_level: int) -> dict:
    """"""Hashes a password with the specified complexity level.""""""
    if not isinstance(password, str):
        return {""error"": ""Invalid input. Password must be a string.""}

    # Generate a salt
    salt = bcrypt.gensalt(complexity_level)

    try:
        hashed_password = bcrypt.hashpw(password.encode('utf-8'), salt)
        return {
            ""hashed_password"": hashed_password.decode('utf-8'),
            ""salt"": salt.decode('utf-8')
        }
    except Exception as e:
        return {""error"": f""Hashing error: {e}""}

def store_password(hashed_data: dict) -> bool:
    """"""Stores the hashed password and its complexity level in the database.""""""
    if not all(key in hashed_data for key in [""hashed_password"", ""salt""]):
        return False

    # Simulate storing data with a timestamp
    current_time = datetime.now()
    database[hashed_data[""hashed_password""]] = {
        ""timestamp"": current_time,
        ""complexity_level"": len(hashed_data[""salt""].split('$')[2])
    }
    return True

def retrieve_original_password(hashed_password: str, complexity_level: int) -> str:
    """"""Retrieves the original password from the hashed password and complexity level.""""""
    if hashed_password not in database or database[hashed_password][""complexity_level""] != complexity_level:
        return ""Password not found or complexity mismatch.""

    # Simulate retrieving data
    stored_data = database[hashed_password]
    try:
        # Check if the password is still valid based on the stored timestamp
        age = datetime.now() - stored_data[""timestamp""]
        if age > timedelta(days=365):  # Passwords older than a year are considered expired
            return ""Password has expired.""

        # Placeholder for actual password retrieval logic
        return ""Original password retrieved successfully.""
    except Exception as e:
        return f""Error retrieving original password: {e}""

def adjust_complexity_level(hashed_password: str) -> bool:
    """"""Adjusts the complexity level of the stored hashed password.""""""
    if hashed_password not in database:
        return False

    # Simulate adjusting complexity
    current_complexity = len(database[hashed_password][""salt""].split('$')[2])
    new_complexity = current_complexity + 1  # Increment complexity for demonstration
    salt = bcrypt.gensalt(new_complexity)

    try:
        hashed_password = bcrypt.hashpw(hashed_password.encode('utf-8'), salt)
        database[hashed_password] = {
            ""timestamp"": datetime.now(),
            ""complexity_level"": new_complexity
        }
        return True
    except Exception as e:
        return f""Error adjusting complexity: {e}""

# Example usage
