from flask import Flask, request, jsonify

app = Flask(__name__)

# In-memory storage for resources
resources = {}

@app.route('/update_resource', methods=['POST'])
def update_resource():
    data = request.json
    resource_id = data.get('id')
    new_attributes = data.get('attributes')

    if resource_id in resources:
        resources[resource_id].update(new_attributes)
        return jsonify(resources[resource_id]), 200
    else:
        return jsonify({'error': 'Resource not found'}), 404

@app.route('/replace_resource', methods=['PUT'])
def replace_resource():
    data = request.json
    resource_id = data.get('id')
    new_attributes = data.get('attributes')

    if resource_id in resources:
        resources[resource_id] = new_attributes
        return jsonify(resources[resource_id]), 200
    else:
        return jsonify({'error': 'Resource not found'}), 404

if __name__ == '__main__':
    app.run(debug=True)
