def check_style_tags(html_str):
    style_tag_start = ""<style>""
    style_tag_end = ""</style>""
    style_count = 0

    start_index = 0
    while (start_index := html_str.find(style_tag_start, start_index)) != -1:
        style_count += 1
        end_index = html_str.find(style_tag_end, start_index)
        if end_index == -1:
            break
        start_index = end_index + len(style_tag_end)

    print(f""Number of <style> tags: {style_count}"")

    # Validate OAuth2 access token response
    json_str = '{""token_type"":""Bearer"", ""expires_in"":3600}'
    if validate_oauth_token(json_str):
        return f""<html><head>{html_str}</head><body>All <style> tags are valid.</body></html>""
    else:
        return ""<html><body>Error: Invalid OAuth2 access token response.</body></html>""

