import pandas as pd
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler, OneHotEncoder
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.svm import SVC
from sklearn.neural_network import MLPClassifier
import requests

class DataProcessingAPI:
    def __init__(self, preprocessing_steps, feature_extractors, models):
        self.pipeline = Pipeline([
            ('preprocessing', preprocessing_steps),
            ('feature_extraction', feature_extractors),
            ('model', models)
        ])

    def process_data(self, data):
        return pd.DataFrame(data)

    def update_resource(self, identifier, resource_data):
        get_response = requests.get(f'http://example.com/resources/{identifier}')
        if get_response.status_code == 200:
            put_response = requests.put(f'http://example.com/resources/{identifier}', json=resource_data)
            return put_response
        else:
            raise ValueError(""Resource not found"")

    def delete_resource(self, identifier):
        response = requests.delete(f'http://example.com/resources/{identifier}')
        if response.status_code == 204:
            return True
        else:
            raise ValueError(""Failed to delete resource"")

    def create_resource(self, new_data):
        response = requests.post('http://example.com/resources', json=new_data)
        if response.status_code == 201:
            return response.json()
        else:
            raise ValueError(""Failed to create resource"")

# Example usage
preprocessing_steps = Pipeline([
    ('scaler', StandardScaler()),
    ('encoder', OneHotEncoder())
])

feature_extractors = TfidfVectorizer()

models = SVC()

dp_api = DataProcessingAPI(preprocessing_steps, feature_extractors, models)

data = {'feature1': [1, 2, 3], 'feature2': ['a', 'b', 'c']}
processed_data = dp_api.process_data(data)

# Update resource example
update_response = dp_api.update_resource('resource_id', {'new_feature': 'new_value'})

# Delete resource example
delete_success = dp_api.delete_resource('resource_id')

# Create resource example
create_response = dp_api.create_resource({'new_feature': 'new_value'})
