import requests

class DataProcessingAPI:
    def __init__(self, preprocessing_steps=[], feature_extraction_algorithms=[], machine_learning_models=[]):
        self.preprocessing_steps = preprocessing_steps
        self.feature_extraction_algorithms = feature_extraction_algorithms
        self.machine_learning_models = machine_learning_models

    def process_data(self, input_data):
        for step in self.preprocessing_steps:
            input_data = step(input_data)
        return input_data

    def extract_features(self, processed_data):
        for algorithm in self.feature_extraction_algorithms:
            processed_data = algorithm.fit_transform(processed_data)
        return processed_data

    def train_model(self, X_train, y_train):
        for model in self.machine_learning_models:
            model.fit(X_train, y_train)

    def update_resource(self, identifier: str, resource_data: dict):
        response = requests.get(f'http://api.example.com/resources/{identifier}')
        if response.status_code == 200:
            resource_info = response.json()
            if 'error' in resource_info:
                raise Exception(resource_info['error'])
            requests.put(f'http://api.example.com/resources/{identifier}', json=resource_data)
            print(""Resource updated successfully"")
        else:
            raise Exception(""Resource not found or update failed"")

    def delete_resource(self, identifier: str):
        response = requests.delete(f'http://api.example.com/resources/{identifier}')
        if response.status_code != 204:
            raise Exception(""Resource deletion failed"")

    def create_resource(self, new_resource: dict):
        requests.post('http://api.example.com/resources', json=new_resource)
