import random

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_information_tag, rnti, crc_indication_rel8_tag):
        self.rx_ue_information_tag = rx_ue_information_tag
        self.rnti = rnti
        self.crc_indication_rel8_tag = crc_indication_rel8_tag

def generate_nfaapi_crc_pdu_array(n):
    return [NFAPI_CRC_INDICATION_PDU_T(
        rx_ue_information_tag=random.randint(1, 100),
        rnti=random.randint(1000, 9999),
        crc_indication_rel8_tag=random.choice([True, False])
    ) for _ in range(n)]

class WeatherData:
    def __init__(self):
        self.data = {}

    def add_weather_data(self, location, weather_info):
        self.data[location] = weather_info

    def serialize(self):
        import json
        return json.dumps(self.data)

    @staticmethod
    def deserialize(serialized_data):
        import json
        data_dict = json.loads(serialized_data)
        weather_data_instance = WeatherData()
        for location, weather_info in data_dict.items():
            weather_data_instance.add_weather_data(location, weather_info)
        return weather_data_instance

def find_and_extract_email_domain(emails):
    domains = set()
    for email in emails:
        parts = email.split('@')
        if len(parts) == 2:
            domain = parts[1]
            domains.add(domain)
    return sorted(list(domains))

# Example usage
emails = [
    ""alice@example.com"",
    ""bob@sample.com"",
    ""charlie@example.com"",
    ""david@sample.com""
]

crc_pdu_array = generate_nfaapi_crc_pdu_array(5)
weather_data = WeatherData()
weather_data.add_weather_data(""New York"", {""temperature"": 15, ""humidity"": 80})
weather_data.add_weather_data(""Los Angeles"", {""temperature"": 25, ""humidity"": 60})

serialized_weather_data = weather_data.serialize()
deserialized_weather_data = WeatherData.deserialize(serialized_weather_data)

sorted_domains = find_and_extract_email_domain(emails)

print(""CRC PDU Array:"", crc_pdu_array)
print(""Serialized Weather Data:"", serialized_weather_data)
print(""Deserialized Weather Data:"", deserialized_weather_data.data)
print(""Sorted Email Domains:"", sorted_domains)
