)

# Route for Google login
@app.route('/login/google')
def google_login():
    redirect_uri = url_for('googleauthorize', _external=True)
    return google.authorize_redirect(redirect_uri)

@app.route('/login/twitter')
def twitter_login():
    redirect_uri = url_for('twitterauthorize', _external=True)
    return twitter.authorize_redirect(redirect_uri)

# Route for Facebook login
@app.route('/login/facebook')
def facebook_login():
    redirect_uri = url_for('facebookauthorize', _external=True)
    return facebook.authorize_redirect(redirect_uri)

# Callback routes for OAuth
@app.route('/callback/google')
def googleauthorize():
    token = google.authorize_access_token()
    resp = google.get('userinfo')
    user_info = resp.json()
    session['user'] = user_info
    return redirect(url_for('home'))

@app.route('/callback/twitter')
def twitterauthorize():
    token = twitter.authorize_access_token()
    resp = twitter.get('account/verify_credentials', params={'include_email': 'true'})
    user_info = resp.json()
    session['user'] = user_info
    return redirect(url_for('home'))

@app.route('/callback/facebook')
def facebookauthorize():
    token = facebook.authorize_access_token()
    resp = facebook.get('me?fields=id,name,email,picture.type(large)')
    user_info = resp.json()
    session['user'] = user_info
    return redirect(url_for('home'))

# Home route to display user information
@app.route('/')
def home():
    if 'user' in session:
        return f""Welcome {session['user']['name']}! <a href='/logout'>Logout</a>""
    else:
        return ""Please login.""

# Logout route
@app.route('/logout')
def logout():
    session.pop('user', None)
    return redirect(url_for('home'))

if __name__ == '__main__':
    app.run(debug=True)
