            input_str_part1 += salt + input_str_part2

    hashed_string_bytes = (input_str + salt).encode('utf-8')

    for _ in range(iteration_count):
        hasher.update(hashed_string_bytes)

    result_hash_bytes = hasher.digest()

    end_time = time.time()

    logging.info(f""Hashing operation completed in {end_time - start_time:.4f} seconds."")

    if output_format.lower() == 'hex':
        result_hash_hexadecimal = result_hash_bytes.hex()

        if cache_hashes and cache_file_path:
