                timestamped_entry = f""{time.strftime('%Y-%m-%d %H:%M:%S')} - {algorithm}: {input_str}: {result_hash_hexadecimal}\n""
                cache_file.write(timestamped_entry)

        return result_hash_hexadecimal

    elif output_format.lower() == 'base64':
        return result_hash_bytes.decode('utf-8').replace('\n', '')
