import os
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import hashes, hmac
from concurrent.futures import ThreadPoolExecutor
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class AESCipher:
    def __init__(self, key_length=32):
        self.key_length = key_length
        self.backend = default_backend()

    def validate_key(self, key):
        if len(key) != self.key_length or not key.isalnum():
            raise ValueError(""Invalid key length. Key must be alphanumeric and match the specified length."")

    def generate_key(self):
        return os.urandom(self.key_length)

    def encrypt(self, data, key=None, mode=modes.ECB):
        if key is None:
            key = self.generate_key()
        else:
            self.validate_key(key)

        iv = os.urandom(16)  # AES block size
        cipher = Cipher(algorithms.AES(key), mode(mode(iv)), backend=self.backend)
        encryptor = cipher.encryptor()
        return iv + encryptor.update(data) + encryptor.finalize()

    def decrypt(self, data, key=None):
        if key is None:
            key = self.generate_key()
        else:
            self.validate_key(key)

        iv = data[:16]
        ciphertext = data[16:]
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=self.backend)
        decryptor = cipher.decryptor()
        return decryptor.update(ciphertext) + decryptor.finalize()

class HMACEncryption:
    def __init__(self, key_length=32):
        self.key_length = key_length
        self.backend = default_backend()

    def generate_key(self):
        return os.urandom(self.key_length)

    def encrypt_with_hmac(self, data, key=None, salt=os.urandom(16)):
        if key is None:
            key = self.generate_key()
        else:
            self.validate_key(key)

        hmac_key = os.urandom(32)  # AES key length
        hmac_obj = hmac.HMAC(hmac_key, hashes.SHA256(), backend=self.backend)
        hmac_obj.update(data + salt)
        mac_tag = hmac_obj.finalize()
        return data + mac_tag

    def validate_hmac(self, data, mac):
        original_data = data[:-32]
        calculated_mac = self.encrypt_with_hmac(original_data, key=None)[-32:]
        if not hmac.compare_digest(mac, calculated_mac):
            raise ValueError(""HMAC validation failed."")

# Example usage
aes_cipher = AESCipher(key_length=32)
data_to_encrypt = b""Sensitive data""
encrypted_data = aes_cipher.encrypt(data_to_encrypt)

hmac_encryption = HMACEncryption()
encrypted_with_hmac = hmac_encryption.encrypt_with_hmac(encrypted_data, salt=b'CustomSalt')
