from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import hashes, hmac
from cryptography.fernet import Fernet
import os
import concurrent.futures

def generate_key(password: str, salt: bytes, key_length: int) -> bytes:
    kdf = PBKDF2HMAC(
        algorithm=hashes.SHA256(),
        length=key_length,
        salt=salt,
        iterations=100000,
        backend=default_backend()
    )
    return kdf.derive(password.encode())

def encrypt_data(data: bytes, key: bytes, mode: str, iv=None) -> bytes:
    if mode == 'ECB':
        cipher = Cipher(algorithms.AES(key), modes.ECB(), backend=default_backend())
    elif mode == 'CBC':
        iv = os.urandom(16)
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
    # Add support for other modes (CFB, GCM) here
    else:
        raise ValueError(""Unsupported encryption mode"")

    encryptor = cipher.encryptor()
    return iv + encryptor.update(data) + encryptor.finalize()

def decrypt_data(encrypted_data: bytes, key: bytes, mode: str, iv=None) -> bytes:
    if mode == 'ECB':
        cipher = Cipher(algorithms.AES(key), modes.ECB(), backend=default_backend())
    elif mode == 'CBC':
        iv = encrypted_data[:16]
        encrypted_data = encrypted_data[16:]
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), backend=default_backend())
    # Add support for other modes (CFB, GCM) here
    else:
        raise ValueError(""Unsupported encryption mode"")

    decryptor = cipher.decryptor()
    return decryptor.update(encrypted_data) + decryptor.finalize()

def generate_hmac(data: bytes, key: bytes) -> bytes:
    hmac_obj = hmac.HMAC(key, hashes.SHA256(), backend=default_backend())
    hmac_obj.update(data)
    return hmac_obj.digest()

def verify_hmac(data: bytes, hmac_value: bytes, key: bytes) -> bool:
    hmac_obj = hmac.HMAC(key, hashes.SHA256(), backend=default_backend())
    hmac_obj.update(data)
    try:
        hmac_obj.verify(hmac_value)
        return True
    except Exception as e:
        return False

def parallel_decryption(encrypted_data_list: list, key: bytes, mode: str):
    with concurrent.futures.ThreadPoolExecutor() as executor:
        decrypted_futures = [executor.submit(decrypt_data, data, key, mode) for data in encrypted_data_list]
        results = [future.result() for future in concurrent.futures.as_completed(decrypted_futures)]
    return results

def generate_password(length: int, complexity: str = 'medium') -> str:
    if complexity == 'simple':
        characters = 'abcdefghijklmnopqrstuvwxyz0123456789'
    elif complexity == 'complex':
        characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()_+'
    else:
        raise ValueError(""Unsupported password complexity"")

    return ''.join(os.urandom(length).decode('utf-8') for _ in range(length))

def create_audit_log(activity: str) -> None:
    with open('audit.log', 'a') as log_file:
        log_file.write(f""{activity}\n"")

