from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding, hashes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.asymmetric import rsa, padding as asym_padding
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from cryptography.hazmat.primitives import serialization
import os
import time
import json

class EnhancedEncryptionService:
    def __init__(self, aes_mode='CBC', aes_padding='PKCS7', rsa_padding='PKCS1v15', caching=True):
        self.aes_mode = modes.__dict__[aes_mode]
        self.aes_padding = padding.PKCS7 if aes_padding == 'PKCS7' else padding.ISO10126
        self.rsa_padding = asym_padding.PKCS1v15 if rsa_padding == 'PKCS1v15' else asym_padding.OAEP
        self.caching = caching
        self.aes_cache = {}
        self.rsa_cache = {}
        self.salted_passwords_storage = {}

    def encrypt(self, data, key_type='AES', key=None):
        if key_type == 'AES':
            return self.encrypt_aes(data, key)
        elif key_type == 'RSA':
            return self.encrypt_rsa(data, key)

    def decrypt(self, encrypted_data, key_type='AES', key=None):
        if key_type == 'AES':
            return self.decrypt_aes(encrypted_data, key)
        elif key_type == 'RSA':
            return self.decrypt_rsa(encrypted_data, key)

    def encrypt_aes(self, data, key):
        if not key:
            raise ValueError(""Key is required for AES encryption"")
        if self.caching and key in self.aes_cache:
            return self.aes_cache[key]
        padder = self.aes_padding(32)
        padded_data = padder.update(data.encode()) + padder.finalize()
        cipher = Cipher(algorithms.AES(key), self.aes_mode(os.urandom(16)), backend=default_backend())
        encryptor = cipher.encryptor()
        encrypted_data = encryptor.update(padded_data) + encryptor.finalize()
        if self.caching:
            self.aes_cache[key] = encrypted_data
        return encrypted_data

    def decrypt_aes(self, encrypted_data, key):
        if not key:
            raise ValueError(""Key is required for AES decryption"")
        if self.caching and key in self.aes_cache:
            return self.aes_cache[key]
        cipher = Cipher(algorithms.AES(key), self.aes_mode(os.urandom(16)), backend=default_backend())
        decryptor = cipher.decryptor()
        decrypted_padded_data = decryptor.update(encrypted_data) + decryptor.finalize()
        unpadder = self.aes_padding(32).unpadder()
        data = unpadder.update(decrypted_padded_data) + unpadder.finalize()
        if self.caching:
            self.aes_cache[key] = data
        return data.decode()

    def encrypt_rsa(self, data, key):
        if not key:
            raise ValueError(""Key is required for RSA encryption"")
        if self.caching and key in self.rsa_cache:
            return self.rsa_cache[key]
        encrypted_data = key.encrypt(data.encode(), self.rsa_padding)
        if self.caching:
            self.rsa_cache[key] = encrypted_data
        return encrypted_data

    def decrypt_rsa(self, encrypted_data, key):
        if not key:
            raise ValueError(""Key is required for RSA decryption"")
        if self.caching and key in self.rsa_cache:
            return self.rsa_cache[key]
        decrypted_data = key.decrypt(encrypted_data, self.rsa_padding)
        if self.caching:
            self.rsa_cache[key] = decrypted_data
        return decrypted_data.decode()

    def generate_rsa_key(self):
        return rsa.generate_private_key(
            public_exponent=65537,
            key_size=2048,
            backend=default_backend()
        )

    def generate_aes_key(self):
        return os.urandom(32)

    def get_current_timestamp(self, precision='ms'):
        if precision == 'ms':
            return time.time() * 1000
        elif precision == 'us':
            return time.time_ns()

    def add_salt_for_user(self, user_id, salt):
        self.salted_passwords_storage[user_id] = {'salt': salt}

    def delete_salt_for_user(self, user_id):
        if user_id in self.salted_passwords_storage:
            del self.salted_passwords_storage[user_id]

    def update_salt_for_user(self, user_id, new_salt):
        if user_id in self.salted_passwords_storage:
            self.salted_passwords_storage[user_id]['salt'] = new_salt

    def password_strength_evaluator(self, password):
        criteria = {
            'length': len(password) >= 8,
            'uppercase': any(char.isupper() for char in password),
            'lowercase': any(char.islower() for char in password),
            'digits': any(char.isdigit() for char in password),
            'special_chars': any(not char.isalnum() for char in password)
        }
        return criteria

    def encrypt_password(self, user_id, password):
        if user_id not in self.salted_passwords_storage:
            salt = os.urandom(16)
            self.add_salt_for_user(user_id, salt)
        else:
            salt = self.salted_passwords_storage[user_id]['salt']
        hashed_password = hashes.Hash(hashes.SHA256(), backend=default_backend()).update(password.encode() + salt).finalize()
        encrypted_hashed_password = self.encrypt(bytes(hashed_password), key_type='AES', key=self.generate_aes_key())
        return encrypted_hashed_password

