import hashlib
import base64
import time
from functools import lru_cache

class FSA:
    def __init__(self, states):
        self.states = states

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, data):
        self.data = data

def generate_unique_RNTI(state_id):
    # Placeholder for generating a unique RNTI value
    return f""RNTI_{state_id}""

def validate_crc_flag(crc_flag):
    # Placeholder for CRC flag validation
    if crc_flag not in ['valid', 'invalid']:
        print(""Invalid CRC flag detected. Freeing allocated memory."")
        raise ValueError(""Invalid CRC flag"")

@lru_cache(maxsize=None)
def hash_value(data, algorithm='sha256', iteration_count=1, encoding='hex'):
    for _ in range(iteration_count):
        data = hashlib.new(algorithm, data.encode()).hexdigest()
    if encoding == 'base64':
        return base64.b64encode(data.encode()).decode()
    return data

def createFSANFAPIPDU(fsa, salt_location='prefix', algorithm='sha256', iteration_count=1, encoding='hex'):
    pdus = []
    for i, state in enumerate(fsa.states):
        rnti = generate_unique_RNTI(i)
        if salt_location == 'prefix':
            data = f""{salt_location}_{rnti}{state}""
        elif salt_location == 'suffix':
            data = f""{rnti}_{salt_location}{state}""
        else:
            data = rnti[:len(rnti)//2] + salt_location + rnti[len(rnti)//2:]

        hashed_value = hash_value(data, algorithm=algorithm, iteration_count=iteration_count, encoding=encoding)
        pdu = NFAPI_CRC_INDICATION_PDU_T(hashed_value)
        pdus.append(pdu)

    return pdus

# Example usage
fsa = FSA(states=['state1', 'state2', 'state3'])
pdus = createFSANFAPIPDU(fsa, salt_location='middle', algorithm='md5', iteration_count=5, encoding='base64')
for pdu in pdus:
    print(pdu.data)
