def secure_password_generator(length=12, charset=None, hashing='sha256', salt=None):
    if not charset:
        charset = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()'

    import random
    password_parts = [
        ''.join(random.choice(charset) for _ in range(length // 3)),
        ''.join(random.choice('abcdefghijklmnopqrstuvwxyz') for _ in range(length // 3)),
        ''.join(random.choice('ABCDEFGHIJKLMNOPQRSTUVWXYZ') for _ in range(length // 3)),
        ''.join(random.choice('0123456789') for _ in range(length // 3)),
        ''.join(random.choice('!@#$%^&*()') for _ in range(length // 3))
    ]
    password = ''.join(random.sample(charset, length)).join(password_parts)

    if salt:
        password += salt

    return hashlib.new(hashing, password.encode()).hexdigest()

# Example usage
