    am = AccountManager()
    request_byte = base64.b64encode(am.encrypt_data(""register:user1:password123""))
    am.process_request(request_byte)

    secure_password = secure_password_generator(length=16, charset='abcdefg', hashing='sha512')
    print(f""Secure Password: {secure_password}"")
