def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def sum_of_primes(numbers):
    if not all(isinstance(n, int) for n in numbers):
        raise ValueError(""All elements in the list must be integers."")

    prime_sum = 0
    for number in numbers:
        if is_prime(number):
            prime_sum += number

    return prime_sum

# Example usage
try:
    numbers = [2, 3, 4, 5, 'a', 7]
    print(sum_of_primes(numbers))  # This should raise an error
except ValueError as e:
    print(e)  # Output: All elements in the list must be integers.
