class FileCompressionUtility:
    def __init__(self):
        self.compression_methods = {
            'lzma': lzma,
            'brotli': brotli,
            'zstd': zstd
        }
        self.encryption_algorithms = {
            'aes_ecb': (algorithms.AES, modes.ECB),
            'aes_cbc': (algorithms.AES, modes.CBC),
            'aes_ctr': (algorithms.AES, modes.CTR)
        }

    def compress(self, data, method='lzma', level=9):
        return self.compression_methods[method].compress(data, level)

    def decompress(self, data, method='lzma'):
        return self.compression_methods[method].decompress(data)

    def encrypt(self, data, key, algorithm='aes_ecb', mode=modes.ECB):
        cipher = Cipher(algorithm(key), mode, backend=default_backend())
        encryptor = cipher.encryptor()
        return encryptor.update(data) + encryptor.finalize()

    def decrypt(self, data, key, algorithm='aes_ecb', mode=modes.ECB):
        cipher = Cipher(algorithm(key), mode, backend=default_backend())
        decryptor = cipher.decryptor()
        return decryptor.update(data) + decryptor.finalize()

