from enum import Enum
from typing import Union, Tuple

class HashAlgorithm(Enum):
    MD5 = 'md5'
    SHA1 = 'sha1'
    SHA256 = 'sha256'

class CustomException(Exception):
    pass

class HashingUtility:
    def __init__(self, iteration_count: int = 10000, salt_location: str = ""prefix"", encoding: str = ""utf-8""):
        self.iteration_count = iteration_count
        self.salt_location = salt_location
        self.encoding = encoding

    def hash_string(self, input_string: str, algorithm: HashAlgorithm, salt: str) -> Union[str, Tuple[str, float]]:
        start_time = time.time()
        salted_string = self._add_salt(input_string, salt)
        hashed_value = self._generate_hash(salted_string, algorithm)

        end_time = time.time()
        execution_time = end_time - start_time

        if self.encoding == ""hex"":
            hashed_value_hex_encoded = hashed_value.hex()
            return hashed_value_hex_encoded, execution_time
        elif self.encoding == ""base64"":
            hashed_value_base64_encoded = hashed_value.hex().encode().decode('utf-8')
            return hashed_value_base64_encoded, execution_time

    def _add_salt(self, input_string: str, salt: str) -> str:
        if not input_string:
            raise CustomException(""Input string cannot be null or empty"")

        if self.salt_location == ""prefix"":
            return f""{salt}{input_string}""
        elif self.salt_location == ""suffix"":
            return f""{input_string}{salt}""
