import random

class NFAPI_CRC_INDICATION_PDU_T:
    def __init__(self, rx_ue_information_tag, rnti, crc_indication_rel8_tag):
        self.rx_ue_information_tag = rx_ue_information_tag
        self.rnti = rnti
        self.crc_indication_rel8_tag = crc_indication_rel8_tag

    def to_dict(self):
        return {
            ""RX_UE_INFORMATION_TAG"": self.rx_ue_information_tag,
            ""RNTI"": self.rnti,
            ""CRC_INDICATION_REL8_TAG"": self.crc_indication_rel8_tag
        }

class WeatherData:
    def __init__(self, location, temperature, humidity):
        self.location = location
        self.temperature = temperature
        self.humidity = humidity

    def serialize(self):
        return f""{self.location},{self.temperature},{self.humidity}""

    @staticmethod
    def deserialize(data):
        location, temperature, humidity = data.split(',')
        return WeatherData(location.strip(), float(temperature), int(humidity))

def generate_nfaapi_cr_indication_pdus(n):
    pdus = []
    for _ in range(n):
        rx_ue_information_tag = random.randint(1, 100)
        rnti = random.randint(1000, 9999)
        crc_indication_rel8_tag = random.choice([True, False])
        pdu = NFAPI_CRC_INDICATION_PDU_T(rx_ue_information_tag, rnti, crc_indication_rel8_tag)
        pdus.append(pdu.to_dict())
    return pdus

def find_and_extract_email_domain(emails):
    domains = set()
    for email in emails:
        domain = email.split('@')[1]
        domains.add(domain)
    return sorted(domains)

def main():
    nfaapi_cr_indication_pdus = generate_nfaapi_cr_indication_pdus(5)
    print(""NFAPI CRC Indication PDUs:"", nfaapi_cr_indication_pdus)

    emails = [""alice@example.com"", ""bob@workplace.com"", ""charlie@example.com""]
    domains = find_and_extract_email_domain(emails)
    print(""Email Domains:"", domains)

    weather_data1 = WeatherData(""New York"", 20, 80)
    weather_data2 = WeatherData(""Los Angeles"", 30, 60)
    weather_data_list = [weather_data1.serialize(), weather_data2.serialize()]

    for data in weather_data_list:
        deserialized_weather = WeatherData.deserialize(data)
        print(f""Location: {deserialized_weather.location}, Temperature: {deserialized_weather.temperature}C, Humidity: {deserialized_weather.humidity}%"")

if __name__ == ""__main__"":
    main()
