    def __init__(self, size):
        self.size = size

def generate_random_data(size):
    return bytes(random.getrandbits(8) for _ in range(size))

def create_binary_files(num_files, unique_names, data_generator):
    if num_files > len(unique_names):
        raise ValueError(""Number of files exceeds the number of unique names provided."")

    if not all(isinstance(name, str) for name in unique_names):
        raise TypeError(""All elements in unique_names must be strings."")

    if not isinstance(data_generator, DataGenerator):
        raise TypeError(""data_generator must be an instance of DataGenerator."")

    if data_generator.size <= 0:
        raise ValueError(""Data generator size must be greater than zero."")

    for i in range(num_files):
        file_name = unique_names[i]
        data = generate_random_data(data_generator.size)

        try:
            with open(file_name, 'wb') as file:
                file.write(data)
            print(f""File '{file_name}' created successfully."")
        except IOError as e:
            print(f""Error creating file '{file_name}': {e}"")

# Example usage
data_gen = DataGenerator(1024)  # Create a generator for 1KB data
unique_names = [f'random_data_{i}.bin' for i in range(5)]  # List of unique names
create_binary_files(5, unique_names, data_gen)
