import random

class ProtocolElementTag:
    def __init__(self, tag):
        self.tag = tag

class IPAddress:
    def __init__(self, address):
        self.address = address

class PDUPriorityLevel:
    def __init__(self, level):
        self.level = level

class MessagePDU:
    def __init__(self, protocol_tag, ip_address, pdu_header):
        self.protocol_tag = protocol_tag
        self.ip_address = ip_address
        self.pdu_header = pdu_header

def generate_message_pdus(num_pdus):
    pdus = []
    for _ in range(num_pdus):
        tag = ProtocolElementTag(f""TAG_{random.randint(1, 100)}"")
        address = IPAddress(""192.168.1."" + str(random.randint(1, 254)))
        priority_level = PDUPriorityLevel(random.randint(1, 10))
        pdu_header = PDUPriorityLevel(priority_level.level)
        pdu = MessagePDU(tag, address, pdu_header)
        pdus.append(pdu)
    return pdus

# Example usage
