import os
import random
from typing import List, Tuple, Dict

class DataGenerator:
    def __init__(self, min_size: int = 1024, max_size: int = 1024*1024) -> None:
        self.min_size = min_size
        self.max_size = max_size

    def generate(self, size: int) -> bytes:
        return os.urandom(size)

def validate_input(num_files: int, unique_names: List[str], DataGenerator: DataGenerator) -> Tuple[bool, str]:
    if num_files <= 0:
        return False, ""Number of files must be a positive integer""
    if not isinstance(unique_names, list) or len(unique_names) < num_files:
        return False, ""Unique names list must be a non-empty list with at least as many elements as the number of files""
    if not isinstance(DataGenerator, DataGenerator):
        return False, ""DataGenerator must be an instance of DataGenerator class""

    return True, """"

def create_random_binary_files(num_files: int, unique_names: List[str], generator_struct: DataGenerator) -> Dict[str, bytes]:
    valid_input_check = validate_input(num_files=num_files,
                                       unique_names=unique_names,
                                       DataGenerator=generator_struct)

    if not valid_input_check[0]:
        raise ValueError(valid_input_check[1])

    file_data_dict = {}

    if len(unique_names) >= num_files and all(len(name) > 0 for name in unique_names):

        used_names = set()

        for _ in range(num_files):
            while True:
                file_name = random.choice(unique_names)
                if file_name not in used_names:
                    used_names.add(file_name)
                    break

            file_data_dict[file_name] = generator_struct.generate(random.randint(generator_struct.min_size,
                                                                                 generator_struct.max_size))

            with open(file_name, 'wb') as f:
                f.write(file_data_dict[file_name])

    else:
        raise ValueError(""Insufficient unique names or invalid name structure"")

    return file_data_dict
