import requests

class WebDataParser:
    @staticmethod
    def fetch_and_parse_json(url, filter_keys=None):
        try:
            response = requests.get(url)
            response.raise_for_status()  # Raise an exception for HTTP errors
            data = response.json()

            if filter_keys:
                filtered_data = {key: value for key, value in data.items() if key not in filter_keys}
                return filtered_data

            return data

        except requests.RequestException as e:
