import configparser

def update_config(file_path, section, option, new_value):
    try:
        config = configparser.ConfigParser()
        config.read(file_path)

        if section not in config:
            raise ValueError(f""Section '{section}' not found in the configuration file."")

        if option not in config[section]:
            raise ValueError(f""Option '{option}' not found under section '{section}' in the configuration file."")

        config[section][option] = new_value

        with open(file_path, 'w') as configfile:
            config.write(configfile)

        print(f""Updated '{option}' to '{new_value}' in '{section}' of '{file_path}'"")

    except FileNotFoundError:
        print(f""The file '{file_path}' was not found."")

    except PermissionError:
        print(f""You do not have permission to access the file '{file_path}'."")

    except Exception as e:
        print(f""An error occurred: {e}"")

# Example usage:
