import random
from typing import List, Tuple, Dict

class UnifiedSolution:
    def __init__(self):
        self.nodes: Dict[str, Tuple[int, int]] = {}
        self.weather_conditions: List[Tuple[str, int]] = []

    def initialize_network(self, node_count: int, interface_count: int) -> None:
        for _ in range(node_count):
            offset = random.randint(0, 1024 * 1024)
            key = random.randint(1000000, 9999999)
            self.nodes[f""Node_{_}""] = (offset, key)

        self.generate_weather_conditions(node_count)

    def generate_weather_conditions(self, node_count: int) -> None:
        for _ in range(node_count):
            condition = [""Sunny"", ""Rainy"", ""Cloudy"", ""Snowy"", ""Foggy""]
            temperature_range = random.randint(-50, 50)
            self.weather_conditions.append((random.choice(condition), temperature_range))

    def add_weather_condition(self) -> None:
        if len(self.weather_conditions) < len(self.nodes):
            node_key = random.choice(list(self.nodes.values()))
            condition_index = random.randint(0, len(self.weather_conditions))
            condition_key = hash(f""{node_key[1]}-{condition_index}"")
            self.weather_conditions.append((f""Condition_{condition_index}"", condition_key))

    def validate_allocation(self) -> bool:
        total_allocated_memory = sum([offset for _, offset in self.nodes.values()])
        return total_allocated_memory <= 2 * (1024 * 1024)

    def process_environmental_data(self) -> None:
        if not self.validate_allocation():
            raise MemoryError(""Insufficient memory allocation!"")

        for node_id in sorted(self.nodes.keys()):
            print(f""{node_id}: {self.nodes[node_id]}"")

        print(""\nWeather Conditions:"")
        for condition in sorted(self.weather_conditions):
            print(f""{condition[0]} - Temperature: {condition[1]}"")
