The core operations involve using a hash object to update with data blocks read from the input file until no more data is available. The progress is logged at regular intervals, specifically every 10 times the block size. Upon completion, it calculates the hexadecimal checksum using `.hexdigest()` method on the hash object and checks if there's an output file specified to write the computed checksum there before returning it in a tuple alongside any encountered errors.",680,,"['```python
import hashlib
import os
import logging

def calculate_file_checksum(file_path, block_size=65536, output_file=None):
    logger = logging.getLogger(__name__)
    logger.setLevel(logging.INFO)
    handler = logging.StreamHandler()
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    handler.setFormatter(formatter)
    logger.addHandler(handler)

    try:
        with open(file_path, 'rb') as file:
            hash_object = hashlib.sha256()
            block_count = 0
            while True:
                data = file.read(block_size)
                if not data:
                    break
                hash_object.update(data)
                block_count += 1
                if block_count % 10 == 0:
                    logger.info(f""Processed {block_count * block_size} bytes"")

        checksum_hex = hash_object.hexdigest()
        if output_file:
            with open(output_file, 'w') as out_file:
                out_file.write(checksum_hex)
                logger.info(f""Checksum written to {output_file}"")

        return (checksum_hex, None)

    except FileNotFoundError:
        logger.error(f""File not found: {file_path}"")
        return (None, f""Error: File '{file_path}' not found."")

    except IOError as e:
        logger.error(f""I/O error occurred: {e}"")
        return (None, f""Error: I/O error while reading file '{file_path}'. Details: {e}"")

    except Exception as e:
        logger.error(f""An unexpected error occurred: {e}"")
        return (None, ""Error: An unexpected error occurred."")

