import random

class RlcFailureCause:
    def __init__(self, causes=None):
        self.causes = [""bitError"", ""powerLimit"", ""bandwidthLimit"", ""protocolError"", ""resourceExhaustion""]
        if causes:
            self.causes.extend(causes)

    def get_random_cause(self):
        return random.choice(self.causes)

class RlcEntity:
    def __init__(self, srlc_id: int, drlc_id: int, failure_cause=None):
        self.srlc_id = srlc_id
        self.drlc_id = drlc_id
        if failure_cause is None:
            self.failure_cause = RlcFailureCause().get_random_cause()
        else:
            self.failure_cause = failure_cause

def create_rlc_entities(entity_count: int = 10, min_id: int = 1000, max_id: int = 9999,
                        custom_causes: list[str] | None = None) -> list[RlcEntity]:
    if not (min_id < max_id):
        raise ValueError(""Invalid ID range"")

    rlc_ids = set()
    entities = []

    while len(rlc_ids) < entity_count:
        srlc_id = random.randint(min_id, max_id)
        drlc_id = random.randint(min_id, max_id)

        if srlc_id != drlc_id and srlc_id not in rlc_ids and drlc_id not in rlc_ids:
            rlc_ids.add(srlc_id)
            rlc_ids.add(drlc_id)
            failure_cause = RlcFailureCause(custom_causes).get_random_cause()
            entities.append(RlcEntity(srlc_id, drlc_id, failure_cause))

    return entities

def sort_rlc_entities(entities: list[RlcEntity], key_type: str):
    if key_type == 'srlcId':
        return sorted(entities, key=lambda x: x.srlc_id)
    elif key_type == 'drlcId':
        return sorted(entities, key=lambda x: x.drlc_id)
    elif key_type == 'cause':
        return sorted(entities, key=lambda x: x.failure_cause)
    else:
        raise ValueError(""Invalid key type. Choose from 'srlcId', 'drlcId', or 'cause'."")

# Example usage
entities = create_rlc_entities(5, 100, 200, ['customError'])
sorted_entities_srlc = sort_rlc_entities(entities, 'srlcId')
sorted_entities_drlc = sort_rlc_entities(entities, 'drlcId')
sorted_entities_cause = sort_rlc_entities(entities, 'cause')
