import random

class RLCEntity:
    def __init__(self, srlcId, drlcId, cause):
        self.srlcId = srlcId
        self.drlcId = drlcId
        self.cause = cause

def generate_unique_ids(srlc_id_range, entity_count):
    used_ids = set()
    while len(used_ids) < entity_count:
        srlc_id = random.randint(1, srlc_id_range)
        if srlc_id not in used_ids:
            used_ids.add(srlc_id)
            yield srlc_id

def create_rlc_entities(entity_count=10, rlc_causes=None):
    if rlc_causes is None:
        predefined_causes = [""bitError"", ""powerLimit"", ""bandwidthLimit"", ""protocolError"", ""resourceExhaustion""]
    else:
        predefined_causes = [""bitError"", ""powerLimit"", ""bandwidthLimit"", ""protocolError"", ""resourceExhaustion""] + rlc_causes

    unique_srlc_generator = generate_unique_ids(10000, entity_count)
    unique_drlc_generator = generate_unique_ids(10000, entity_count)

    entities = []

    for _ in range(entity_count):
        try:
            srlc_id = next(unique_srlc_generator)
            drlc_id = next(unique_drlc_generator)
            cause_index = random.randint(0, len(predefined_causes) - 1)
            cause_value = predefined_causes[cause_index]

            entities.append(RLCEntity(srlcId=srlc_id, drlcId=drlc_id, cause=cause_value))

        except StopIteration as e:
            print(f""Error generating unique IDs: {e}"")
            break

    return sorted(entities, key=lambda x: (x.srlcId, x.drcId), reverse=False)

# Example usage
if __name__ == ""__main__"":
    entities_with_custom_causes = create_rlc_entities(entity_count=5,
                                                      rlc_causes=[""hardwareFailure"", ""softwareBug""])

    for entity in entities_with_custom_causes:
        print(f""RLC Entity - Source ID: {entity.srlcId}, Destination ID: {entity.drcId}, Cause: {entity.cause}"")
